import{_ as t,o,c as d,a0 as r}from"./chunks/framework.OED5XGjC.js";const h=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),s={name:"explanation/architecture.md"};function a(i,e,n,c,p,l){return o(),d("div",null,[...e[0]||(e[0]=[r(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Ports-and-adapters over a flat <code>crates/</code> workspace: <code>myco-core</code> is pure domain — item models, the id registry, the state machine — with no I/O. Ports are traits (<code>myco-store</code>, <code>myco-config</code>, <code>myco-index</code>); impls live in separate crates; <code>crates/myco-cli</code> (package <code>myco</code>) is the composition root that wires impls to verbs.</p><p>Design rules:</p><ul><li><strong>No <code>unsafe</code>, no async</strong> — the binary stays dependency-light and synchronous; no runtime to embed.</li><li><strong>Git via the <code>git</code> CLI</strong> — <code>myco-git</code> shells out for the orphan branch, worktree, and per-verb commits; no libgit2/gix binding.</li><li><strong>Markdown is the file spec</strong> — <code>myco-store-md</code> owns strict parse/emit: deterministic output, stable ordering, minimal diffs. <code>myco-testkit</code> freezes emit with golden fixtures and proptest round-trips, so the format can&#39;t drift silently.</li><li><strong>The index is derived, never canonical</strong> — <code>myco-index-redb</code> snapshots ledgers into redb for <code>status</code>/<code>view</code>/<code>org</code>; it can be deleted and rebuilt at any time.</li></ul><table tabindex="0"><thead><tr><th>crate</th><th>layer</th><th>purpose</th></tr></thead><tbody><tr><td><code>myco-core</code></td><td>domain</td><td>myco domain core: item models, ID registry, state machine — pure, no I/O</td></tr><tr><td><code>myco-config</code></td><td>port</td><td>Config port: where myco.toml-shaped config comes from</td></tr><tr><td><code>myco-index</code></td><td>port</td><td>Index port: the derived, disposable cache powering status/board/report/org views</td></tr><tr><td><code>myco-store</code></td><td>port</td><td>Store port: where project/ state (TODO.md, BACKLOG.md, meta.toml, item files) is persisted</td></tr><tr><td><code>myco-ops</code></td><td>ops</td><td>myco — ops I/O shell: project discovery, store open/save, commit-per-mutation, verb plumbing</td></tr><tr><td><code>myco-config-toml</code></td><td>adapter</td><td>Config impl: myco.toml file (explicit path, env, ./, ~/.config)</td></tr><tr><td><code>myco-driver</code></td><td>adapter</td><td>tamias-driver-myco — pavo view driver over a repo&#39;s project/ ledger (reads via myco-ops)</td></tr><tr><td><code>myco-git</code></td><td>adapter</td><td>Git plumbing for myco — shells out to the git CLI; owns the project branch/worktree mechanics</td></tr><tr><td><code>myco-index-redb</code></td><td>adapter</td><td>Index impl: redb snapshots + repos.toml registry under ~/.local/share/myco (disposable derived cache)</td></tr><tr><td><code>myco-shell</code></td><td>adapter</td><td>Run a command in a working directory via bash -c — the generic shell-out helper</td></tr><tr><td><code>myco-store-md</code></td><td>adapter</td><td>Markdown adapter for the store port — strict parse/emit of project/ files, round-trip stable; owns the file spec</td></tr><tr><td><code>myco-testkit</code></td><td>adapter</td><td>Golden fixtures + conformance: frozen md emit snapshots and proptest round-trips for the project/ file spec</td></tr><tr><td><code>myco</code></td><td>binary</td><td>myco — records engine for agent work — views + mutations; project management is the shipped prelude</td></tr></tbody></table><h2 id="the-engine-and-the-prelude" tabindex="-1">The engine and the prelude <a class="header-anchor" href="#the-engine-and-the-prelude" aria-label="Permalink to &quot;The engine and the prelude&quot;">​</a></h2><p>The shape that emerged rather than being designed: <strong>myco is a records + views + mutations engine, and PM is its shipped prelude</strong> (P-009). <code>myco init</code> seeds that prelude — the five <code>[[kinds]]</code>, the builtin views, the registry verbs — so editing config isn&#39;t customizing a PM tool, it&#39;s programming an engine whose default program happens to be project management.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>            engine (code)                      prelude (seeded config)</span></span>
<span class="line"><span>  ┌────────────────────────────────┐    ┌───────────────────────────────┐</span></span>
<span class="line"><span>  │ sources   repo │ index         │    │ [[kinds]]  task issue …       │</span></span>
<span class="line"><span>  │ eval      filter→group→sort    │    │ [views]    board open hot …   │</span></span>
<span class="line"><span>  │ emits     list board md json   │    │ [verbs]    alias view-emit …  │</span></span>
<span class="line"><span>  │ dispatch  one registry table   │    └───────────────────────────────┘</span></span>
<span class="line"><span>  └────────────────────────────────┘</span></span>
<span class="line"><span>      owns, must never be data            declared, layered, shadowable</span></span></code></pre></div><p>A read is <code>universe → eval → emit</code>:</p><table tabindex="0"><thead><tr><th>stage</th><th>knob</th><th>values</th></tr></thead><tbody><tr><td>universe</td><td><code>source</code></td><td><code>repo</code> (this worktree) · <code>index</code> (the registered-repo union)</td></tr><tr><td>eval</td><td><code>filter → group_by → sort → limit</code></td><td>a <code>ViewSpec</code>, from config or flags</td></tr><tr><td>emit</td><td><code>format</code></td><td><code>list</code> · <code>board</code> · <code>md</code> · <code>json</code> · <code>repos</code></td></tr></tbody></table><p>Every feature gets asked one question — <strong>engine or prelude?</strong> Engine answers generalize (a new source, axis or format); prelude answers configure (which kinds, views and verbs ship seeded).</p><h3 id="what-stays-code" tabindex="-1">What stays code <a class="header-anchor" href="#what-stays-code" aria-label="Permalink to &quot;What stays code&quot;">​</a></h3><p>The moat is what must be <em>owned</em> rather than declared: the markdown file spec, atomic commit-per-mutation on <code>project</code>, the state machine, the id registry. <code>Item</code> keeps fixed semantics — a schema DSL over arbitrary fields would make this jq-over-markdown, a different and worse product. Mutations stay code as well: the prelude configures <em>what</em> exists, never <em>how</em> writes behave (ADR-0004, one registry).</p><h2 id="boundary-—-work-memory-only" tabindex="-1">Boundary — work memory only <a class="header-anchor" href="#boundary-—-work-memory-only" aria-label="Permalink to &quot;Boundary — work memory only&quot;">​</a></h2><p>myco owns the ledger of intent (tasks, issues, proposals, plans, ADRs, handoffs). Neighbors own their own memory:</p><ul><li><strong>sturn</strong> — ephemeral coordination (live claims/ops/topics)</li><li><strong>kuda</strong> — code memory; myco indexes work items, not code</li><li><strong>peregrin</strong> — orchestration; it embeds the ledger through <code>myco serve</code> (JSON-RPC 2.0 on stdio — <code>adrs/0001</code>), reachable one-shot via <code>myco batch</code></li><li><strong>bupha</strong> — CI gate; <code>myco check</code> in pipelines, <code>Item:</code> trailers</li><li><strong>mycena</strong> — surfaces TODO/FIXME in code → <code>myco absorb</code></li><li><strong>sepia</strong> — session lifecycle → <code>myco handoff</code> / <code>myco resume</code></li></ul><p>Anything needing a daemon, a multi-machine view, or arbitration between actors belongs to peregrin, not here.</p>`,17)])])}const g=t(s,[["render",a]]);export{h as __pageData,g as default};
